python - <<'PY'
from boltons.iterutils import research, split, split_iter, default_enter

shared = {'value': 7}
root = {'a': shared, 'b': shared}
query = lambda p, k, v: isinstance(v, int)
assert research(root, query) == [(('a', 'value'), 7)]
assert research(root, query, cache=False) == [(('a', 'value'), 7), (('b', 'value'), 7)]
assert research(root, query, False, default_enter, False) == research(root, query, cache=False)
for circular in ([], {}):
    if isinstance(circular, list):
        circular.append(circular)
    else:
        circular['self'] = circular
    assert len(research(circular, cache=True)) == 1
    try:
        research(circular, cache=False)
    except RecursionError:
        pass
    else:
        raise AssertionError('expected RecursionError')
for source in ([1, None, 2], (1, None, 2), iter([1, None, 2]), 'abc', [], iter([])):
    expected = list(source)
    for func in (split, lambda *a, **kw: list(split_iter(*a, **kw))):
        assert func(iter(expected), maxsplit=0) == [expected]
        assert func(tuple(expected), sep=None, maxsplit=0) == [expected]
source = [1, 2]
assert split(source, maxsplit=0)[0] is not source
print('Targeted research/cache and split/maxsplit=0 checks passed')
